// Eingabe der Runtime: { id: string }
const incoming = $input.first().json;
const inp = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
if (typeof inp.id !== 'string' || inp.id.trim() === '') {
  throw new Error('mail-read: Feld "id" fehlt');
}
return [{ json: { messageId: inp.id.trim() } }];

// In die von der Runtime erwartete Form bringen. Anhaenge als base64.
const item = $input.first();
const m = item.json || {};
const payloadHeaders = (m.payload && m.payload.headers) || [];
const h = (name) => {
  const hit = payloadHeaders.find((x) => (x.name || '').toLowerCase() === name);
  return hit ? hit.value : '';
};
const bin = item.binary || {};
const attachments = Object.keys(bin).map((key) => {
  const b = bin[key];
  return {
    filename: b.fileName || key,
    mime_type: b.mimeType || 'application/octet-stream',
    content_base64: b.data || ''
  };
});
return [{ json: {
  id: String(m.id || m.messageId || ''),
  subject: m.subject || h('subject') || '',
  from: m.from || h('from') || '',
  to: m.to || h('to') || '',
  date: m.date || h('date') || m.internalDate || '',
  body_text: (m.text != null ? String(m.text) : ''),
  body_html: (m.textHtml != null ? String(m.textHtml) : (m.html != null ? String(m.html) : '')),
  body_mime: (m.text != null ? 'text/plain' : 'text/html'),
  attachments
} }];
